 p_id=>wwv_flow_api.id(11100102000040)
,p_name=>'IMPR_NBR'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'IMPR_NBR'
,p_data_type=>'NUMBER'
,p_is_query_only=>false
,p_item_type=>'NATIVE_LINK'
,p_heading=>unistr('\0627\0644\0631\0642\0645 \0627\0644\062C\0645\0631\0643\064A')
,p_heading_alignment=>'CENTER'
